// Two surfaces at once: the tablet EUI and the phone EUI, side by side.
//
// The one beat in the promo that `Stage` cannot do, because `Stage` holds a single
// panel with a copy column beside it. Here the two panels *are* the message — the same
// room running on both form factors — so the copy goes above them and the pair is
// centred underneath.
//
// Sizing favours the phone deliberately. At a shared panel height the tablet is 960px
// wide and the phone about 277px, and phone EUI labels do not read at 1080p that small
// — which would leave the beat proving nothing. The tablet has been on screen for five
// preceding beats and can afford to be the smaller of the two here; the phone cannot.
// So the phone is set taller than the tablet, against the intuition that the bigger
// device should be bigger.

import type {ReactNode} from 'react';
import {AbsoluteFill, Easing, Interactive, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {Camera, type Shot} from '../camera/Camera';
import {background, color, font, radius, space, type} from '../design/theme';
import {DitherOverlay} from './DitherOverlay';

/** Frame pixels of device edge around each screen. See `Stage`'s `bezel`. */
const BEZEL = 18;

export const DUAL_STAGE = {
  /** Frame pixels of *screen*; the bezel is drawn outside it. Phone is taller — see above. */
  tabletHeight: 470,
  phoneHeight: 690,
  gap: 72,
  titleTop: 56,
  /**
   * Where the panels may live. The copy block above is eyebrow + a line of Audiowide
   * + a line of body, and the first version centred the panels in the whole frame — so
   * the 880px phone reached up to y=148 and printed straight through the headline.
   * Reserving the band outright is what keeps a taller phone from ever doing that
   * again; the pair centres in what is left.
   *
   * The bottom is a hard edge, not a suggestion. `phoneHeight` plus its bezel has to
   * fit inside this band or the phone runs off the frame — which is exactly what
   * happened at 750 once the bezel added 36px it had never had to account for.
   */
  panelZoneTop: 250,
  panelZoneBottom: 1030,
} as const;

type Panel = {
  contentSize: {width: number; height: number};
  shots: Shot[];
  height: number;
  children: ReactNode;
};

const Panel = ({
  panel,
  left,
  top,
  scale,
  bezelColor,
}: {
  panel: Panel;
  left: number;
  top: number;
  scale?: number;
  bezelColor: string;
}) => {
  const width = (panel.contentSize.width / panel.contentSize.height) * panel.height;

  return (
    <div
      style={{
        position: 'absolute',
        left,
        top,
        width: width + BEZEL * 2,
        height: panel.height + BEZEL * 2,
        padding: BEZEL,
        boxSizing: 'border-box',
        borderRadius: radius.xl,
        backgroundColor: bezelColor,
        border: `1px solid ${color.lineSoft}`,
        boxShadow: `0 40px 120px ${color.scrim}`,
        transformOrigin: 'center center',
        scale: scale !== undefined ? String(scale) : undefined,
      }}
    >
      {/* `position: relative` is load-bearing. <Camera> renders an <AbsoluteFill>, which
          anchors to its nearest *positioned* ancestor — without this that is the panel
          itself, so the screen ignores the padding, sits hard against the left edge, and
          the entire bezel piles up on the right. It reads as the device being cut off. */}
      <div
        style={{
          position: 'relative',
          width,
          height: panel.height,
          overflow: 'hidden',
          borderRadius: radius.sm,
        }}
      >
        <Camera
          contentSize={panel.contentSize}
          shots={panel.shots}
          viewport={{width, height: panel.height}}
        >
          {panel.children}
        </Camera>
      </div>
    </div>
  );
};

export const DualStage = ({
  eyebrow,
  title,
  body,
  at = 0,
  until,
  tablet,
  phone,
  copy,
  panelScale,
  evenPanelSpacing = false,
  bezelColor = color.bezel,
  background: stageBackground = background.stage,
}: {
  eyebrow?: string;
  title?: string;
  body?: ReactNode;
  at?: number;
  /** Beat length; the copy leaves over the 14 frames before it. See StageCopy. */
  until?: number;
  tablet: Omit<Panel, 'height'>;
  phone: Omit<Panel, 'height'>;
  /** Replaces the built-in eyebrow/title/body block outright. */
  copy?: ReactNode;
  panelScale?: number;
  /** Keep both scaled panels and all three horizontal gaps evenly spaced. */
  evenPanelSpacing?: boolean;
  /** Device-body colour. Defaults to the shared video bezel. */
  bezelColor?: string;
  /** Background under the whole stage. Defaults to the house marketing gradient. */
  background?: string;
}) => {
  const frame = useCurrentFrame();
  const {width: frameWidth, height: frameHeight} = useVideoConfig();

  const tabletPanel = {...tablet, height: DUAL_STAGE.tabletHeight};
  const phonePanel = {...phone, height: DUAL_STAGE.phoneHeight};
  const tabletWidth =
    (tablet.contentSize.width / tablet.contentSize.height) * DUAL_STAGE.tabletHeight;
  const phoneWidth =
    (phone.contentSize.width / phone.contentSize.height) * DUAL_STAGE.phoneHeight;

  // Centred as a pair, so the composition does not drift when either panel is retuned.
  // Widths include the bezel: it is part of the device, and leaving it out of the
  // centring is what put the pair off-centre and the phone through the frame edge.
  const pairWidth = tabletWidth + DUAL_STAGE.gap + phoneWidth + BEZEL * 4;
  const pairLeft = (frameWidth - pairWidth) / 2;
  const scale = panelScale ?? 1;
  const tabletOuterWidth = tabletWidth + BEZEL * 2;
  const phoneOuterWidth = phoneWidth + BEZEL * 2;
  const evenGap =
    (frameWidth - tabletOuterWidth * scale - phoneOuterWidth * scale) / 3;
  const tabletLeft = evenPanelSpacing
    ? evenGap - (tabletOuterWidth * (1 - scale)) / 2
    : pairLeft;
  const phoneLeft = evenPanelSpacing
    ? evenGap * 2 + tabletOuterWidth * scale - (phoneOuterWidth * (1 - scale)) / 2
    : pairLeft + tabletWidth + BEZEL * 2 + DUAL_STAGE.gap;
  // Centred in the band below the copy, never in the whole frame.
  const centreY = (DUAL_STAGE.panelZoneTop + Math.min(DUAL_STAGE.panelZoneBottom, frameHeight)) / 2;

  return (
    <AbsoluteFill style={{background: stageBackground, overflow: 'hidden'}}>
      <DitherOverlay />
      {copy ? (
        <div
          style={{
            position: 'absolute',
            left: 0,
            right: 0,
            top: DUAL_STAGE.titleTop,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
          }}
        >
          {copy}
        </div>
      ) : (
      <Interactive.Div
        name="Dual stage copy"
        style={{
          position: 'absolute',
          left: 0,
          right: 0,
          top: DUAL_STAGE.titleTop,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: space(1.5),
          textAlign: 'center',
          opacity: until
            ? interpolate(frame, [until - 14, until], [1, 0], {
                easing: Easing.bezier(0.7, 0, 0.84, 0),
                extrapolateLeft: 'clamp',
                extrapolateRight: 'clamp',
              })
            : 1,
        }}
      >
        {eyebrow ? (
          <Interactive.Div
            name="Dual stage eyebrow"
            style={{
              color: color.accent,
              fontFamily: font.mono,
              fontSize: type.label,
              fontWeight: 700,
              letterSpacing: '0.12em',
              textTransform: 'uppercase',
              opacity: interpolate(frame, [at, at + 14], [0, 1], {
                easing: Easing.bezier(0.16, 1, 0.3, 1),
                extrapolateLeft: 'clamp',
                extrapolateRight: 'clamp',
              }),
            }}
          >
            {eyebrow}
          </Interactive.Div>
        ) : null}

        <Interactive.Div
          name="Dual stage title"
          style={{
            color: color.text,
            fontFamily: font.display,
            fontSize: type.title,
            lineHeight: 0.98,
            letterSpacing: 0,
            opacity: interpolate(frame, [at + 4, at + 20], [0, 1], {
              easing: Easing.bezier(0.16, 1, 0.3, 1),
              extrapolateLeft: 'clamp',
              extrapolateRight: 'clamp',
            }),
            translate: interpolate(frame, [at + 4, at + 24], ['0px 14px', '0px 0px'], {
              easing: Easing.bezier(0.16, 1, 0.3, 1),
              extrapolateLeft: 'clamp',
              extrapolateRight: 'clamp',
            }),
          }}
        >
          {title}
        </Interactive.Div>

        {body ? (
          <Interactive.Div
            name="Dual stage body"
            style={{
              color: color.textMuted,
              fontFamily: font.ui,
              fontSize: type.body,
              lineHeight: 1.45,
              opacity: interpolate(frame, [at + 12, at + 28], [0, 1], {
                easing: Easing.bezier(0.16, 1, 0.3, 1),
                extrapolateLeft: 'clamp',
                extrapolateRight: 'clamp',
              }),
            }}
          >
            {body}
          </Interactive.Div>
        ) : null}
      </Interactive.Div>
      )}

      {/* Both panels scale smoothly on entrance then remain resting */}
      <Panel
        panel={tabletPanel}
        left={tabletLeft}
        top={centreY - (DUAL_STAGE.tabletHeight + BEZEL * 2) / 2}
        scale={panelScale}
        bezelColor={bezelColor}
      />
      <Panel
        panel={phonePanel}
        left={phoneLeft}
        top={centreY - (DUAL_STAGE.phoneHeight + BEZEL * 2) / 2}
        scale={panelScale}
        bezelColor={bezelColor}
      />
    </AbsoluteFill>
  );
};
